#!/usr/bin/env node
// Generates src/tokens/tokens.css from the Figma variable export. Do not edit the output.

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const data = JSON.parse(await readFile(join(root, 'docs/figma-export/variables.json'), 'utf8'));
const { Primitives, Color, Theme } = data.collections;

const cssName = (collection, name) => collection.vars[name].css;
const allVars = { ...Primitives.vars, ...Color.vars, ...Theme.vars };
const aliasTarget = (alias) => `var(${allVars[alias].css})`;

const fontStacks = {
    Fraunces: '"Fraunces", "Noto Sans JP", Georgia, serif',
    Inter: '"Inter", "Noto Sans JP", system-ui, sans-serif',
    'Instrument Sans': '"Instrument Sans", "Noto Sans JP", system-ui, sans-serif',
    Sora: '"Sora", "Noto Sans JP", system-ui, sans-serif',
    'Space Grotesk': '"Space Grotesk", "Noto Sans JP", system-ui, sans-serif',
    'Space Mono': '"Space Mono", "Noto Sans JP", monospace',
};
const weights = { Regular: 400, Medium: 500, SemiBold: 600, Bold: 700 };

const value = (def, raw) => {
    if (raw && typeof raw === 'object' && raw.alias) return aliasTarget(raw.alias);
    if (def.type === 'COLOR') return raw;
    if (def.type === 'STRING') return def.css.startsWith('--font') ? fontStacks[raw] : weights[raw];
    return `${Math.round(raw * 100) / 100}px`;
};

const block = (selector, lines) => `${selector} {\n${lines.map((l) => `    ${l}`).join('\n')}\n}\n`;
const out = ['/* Generated by scripts/build-tokens.mjs from docs/figma-export/variables.json. Do not edit. */\n'];

out.push(
    block(
        ':root',
        Object.values(Primitives.vars).map((d) => `${d.css}: ${value(d, d.v.Value)};`),
    ),
);

for (const mode of Theme.modes) {
    const selector = mode === Theme.modes[0] ? `:root,\n[data-theme='${mode.toLowerCase()}']` : `[data-theme='${mode.toLowerCase()}']`;
    out.push(
        block(
            selector,
            Object.values(Theme.vars).map((d) => `${d.css}: ${value(d, d.v[mode])};`),
        ),
    );
}

for (const mode of Color.modes) {
    const selector = mode === Color.modes[0] ? `:root,\n[data-scheme='${mode.toLowerCase()}']` : `[data-scheme='${mode.toLowerCase()}']`;
    const lines = Object.values(Color.vars).map((d) => `${d.css}: ${value(d, d.v[mode])};`);
    lines.push(`color-scheme: ${mode.toLowerCase()};`);
    out.push(block(selector, lines));
}

// Theme values Figma cannot hold (ADR 2026-09-29-theme-system): display case and tracking.
out.push(block(":root,\n[data-theme='caramel']", ['--display-case: none;', '--display-tracking: 0em;']));
out.push(block("[data-theme='violet']", ['--display-case: uppercase;', '--display-tracking: 0.09em;']));

// Motion has no Figma variable type; one curve and three durations keep every hover effect in step.
out.push(
    block(':root', [
        '--motion-fast: 160ms;',
        '--motion-base: 320ms;',
        '--motion-slow: 700ms;',
        '--ease-out: cubic-bezier(0.2, 0.7, 0.2, 1);',
    ]),
);
out.push(
    `@media (prefers-reduced-motion: reduce) {\n${block(':root', ['--motion-fast: 0ms;', '--motion-base: 0ms;', '--motion-slow: 0ms;'])}}\n`,
);

// Each text style becomes variables (for editorial HTML without classes) and a .type-* class using them.
const slug = (name) => name.split('/')[1].toLowerCase().replace(/\s+/g, '-');
const typeVars = [];
for (const s of data.textStyles) {
    const id = `--type-${slug(s.name)}`;
    const display = s.family === 'font/display';
    const tracking = `${s.tracking / 100}em`;
    typeVars.push(
        `${id}-family: ${s.family.startsWith('font/') ? `var(${cssName(Theme, s.family)})` : fontStacks[s.family]};`,
        `${id}-weight: ${typeof s.weight === 'string' ? `var(${cssName(Theme, s.weight)})` : s.weight};`,
        `${id}-size: ${s.size}px;`,
        `${id}-line-height: ${typeof s.lineHeight === 'string' ? `var(${cssName(Theme, s.lineHeight)})` : `${s.lineHeight}px`};`,
        `${id}-tracking: ${display ? `calc(${tracking} + var(--display-tracking))` : tracking};`,
        `${id}-case: ${s.case === 'UPPER' ? 'uppercase' : display ? 'var(--display-case)' : 'none'};`,
    );
    out.push(
        block(`.type-${slug(s.name)}`, [
            `font-family: var(${id}-family);`,
            `font-weight: var(${id}-weight);`,
            `font-size: var(${id}-size);`,
            `line-height: var(${id}-line-height);`,
            `letter-spacing: var(${id}-tracking);`,
            `text-transform: var(${id}-case);`,
        ]),
    );
}
out.push(block(':root', typeVars));

await mkdir(join(root, 'src/tokens'), { recursive: true });
await writeFile(join(root, 'src/tokens/tokens.css'), out.join('\n'));
console.log(`tokens.css: ${Object.keys(allVars).length} variables, ${data.textStyles.length} text styles`);
